CREATE DATABASE IF NOT EXISTS repairdesk CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE repairdesk;
CREATE TABLE schema_info(version INT NOT NULL PRIMARY KEY);
INSERT INTO schema_info VALUES(0);
CREATE TABLE staff(id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL,login VARCHAR(80) NOT NULL UNIQUE,password_hash VARCHAR(200) NOT NULL,role ENUM('Администратор','Приемщик','Мастер') NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE) ENGINE=InnoDB;
CREATE TABLE clients(id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL,phone VARCHAR(40) NOT NULL,email VARCHAR(180) NOT NULL DEFAULT '',notes TEXT NOT NULL,INDEX ix_client_phone(phone)) ENGINE=InnoDB;
CREATE TABLE orders(
 id INT PRIMARY KEY AUTO_INCREMENT,client_id INT NOT NULL,device_type ENUM('ПК','Ноутбук') NOT NULL,
 device VARCHAR(160) NOT NULL,serial VARCHAR(120) NOT NULL DEFAULT '',complaint TEXT NOT NULL,device_condition TEXT NOT NULL,
 diagnosis TEXT NOT NULL DEFAULT (''),
 status ENUM('Принят','Диагностика','Согласование','Ожидание деталей','В ремонте','Готов','Выдан','Отменен') NOT NULL DEFAULT 'Принят',
 technician_id INT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,due_at DATE NOT NULL,
 paid DECIMAL(12,2) NOT NULL DEFAULT 0,version INT NOT NULL DEFAULT 1,
 FOREIGN KEY(client_id) REFERENCES clients(id),FOREIGN KEY(technician_id) REFERENCES staff(id),
 INDEX ix_order_status(status),INDEX ix_order_technician(technician_id),CHECK(paid>=0)
) ENGINE=InnoDB;
CREATE TABLE parts(
 id INT PRIMARY KEY AUTO_INCREMENT,category VARCHAR(40) NOT NULL,brand VARCHAR(60) NOT NULL,name VARCHAR(160) NOT NULL UNIQUE,
 price DECIMAL(12,2) NOT NULL,stock INT NOT NULL DEFAULT 0,min_stock INT NOT NULL DEFAULT 1,
 socket VARCHAR(30) NOT NULL DEFAULT '',memory_type VARCHAR(30) NOT NULL DEFAULT '',wattage INT NOT NULL DEFAULT 0,
 capacity INT NOT NULL DEFAULT 0,length_mm INT NOT NULL DEFAULT 0,form_factor VARCHAR(30) NOT NULL DEFAULT '',
 supported_forms VARCHAR(100) NOT NULL DEFAULT '',max_gpu_mm INT NOT NULL DEFAULT 0,max_memory_gb INT NOT NULL DEFAULT 0,
 cpu_support TEXT NOT NULL DEFAULT (''),power_connectors VARCHAR(100) NOT NULL DEFAULT '',source_url VARCHAR(600) NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT (''),
 CHECK(price>=0),CHECK(stock>=0),CHECK(min_stock>=0)
) ENGINE=InnoDB;
CREATE TABLE services(id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(160) NOT NULL UNIQUE,price DECIMAL(12,2) NOT NULL,CHECK(price>=0)) ENGINE=InnoDB;
CREATE TABLE order_lines(id INT PRIMARY KEY AUTO_INCREMENT,order_id INT NOT NULL,kind ENUM('Работа','Запчасть') NOT NULL,part_id INT NULL,name VARCHAR(160) NOT NULL,quantity INT NOT NULL,unit_price DECIMAL(12,2) NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(part_id) REFERENCES parts(id),CHECK(quantity>0),CHECK(unit_price>=0)) ENGINE=InnoDB;
CREATE TABLE payments(id INT PRIMARY KEY AUTO_INCREMENT,order_id INT NOT NULL,staff_id INT NOT NULL,amount DECIMAL(12,2) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(staff_id) REFERENCES staff(id)) ENGINE=InnoDB;
CREATE TABLE order_events(id INT PRIMARY KEY AUTO_INCREMENT,order_id INT NOT NULL,staff_id INT NOT NULL,message VARCHAR(600) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(staff_id) REFERENCES staff(id)) ENGINE=InnoDB;
CREATE TABLE stock_moves(id INT PRIMARY KEY AUTO_INCREMENT,part_id INT NOT NULL,staff_id INT NOT NULL,order_id INT NULL,quantity INT NOT NULL,reason VARCHAR(250) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(part_id) REFERENCES parts(id),FOREIGN KEY(staff_id) REFERENCES staff(id),FOREIGN KEY(order_id) REFERENCES orders(id)) ENGINE=InnoDB;
CREATE TABLE games(id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL UNIQUE);
CREATE TABLE benchmarks(id INT PRIMARY KEY AUTO_INCREMENT,game_id INT NOT NULL,gpu_id INT NOT NULL,test_cpu VARCHAR(200) NOT NULL,width INT NOT NULL,height INT NOT NULL,preset VARCHAR(160) NOT NULL,ray_tracing VARCHAR(80) NOT NULL,upscaling VARCHAR(100) NOT NULL,average_fps DECIMAL(8,2) NOT NULL,low_fps DECIMAL(8,2) NULL,source_title VARCHAR(200) NOT NULL,source_url VARCHAR(600) NOT NULL,test_date DATE NOT NULL,notes TEXT NOT NULL,FOREIGN KEY(game_id) REFERENCES games(id),FOREIGN KEY(gpu_id) REFERENCES parts(id),CHECK(average_fps>0),INDEX ix_bench_gpu_resolution(gpu_id,width));
CREATE TABLE builds(id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(150) NOT NULL,client_id INT NULL,staff_id INT NOT NULL,total DECIMAL(12,2) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(client_id) REFERENCES clients(id),FOREIGN KEY(staff_id) REFERENCES staff(id));
CREATE TABLE build_parts(build_id INT NOT NULL,part_id INT NOT NULL,price DECIMAL(12,2) NOT NULL,PRIMARY KEY(build_id,part_id),FOREIGN KEY(build_id) REFERENCES builds(id),FOREIGN KEY(part_id) REFERENCES parts(id));
CREATE TABLE estimates(id INT PRIMARY KEY AUTO_INCREMENT,order_id INT NOT NULL,status ENUM('Черновик','Согласована','Отклонена','Применена') NOT NULL DEFAULT 'Черновик',note VARCHAR(2000) NOT NULL DEFAULT '',approved_by VARCHAR(120) NOT NULL DEFAULT '',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE estimate_lines(id INT PRIMARY KEY AUTO_INCREMENT,estimate_id INT NOT NULL,part_id INT NULL,name VARCHAR(160) NOT NULL,quantity INT NOT NULL,unit_price DECIMAL(12,2) NOT NULL,FOREIGN KEY(estimate_id) REFERENCES estimates(id) ON DELETE CASCADE,FOREIGN KEY(part_id) REFERENCES parts(id),CHECK(quantity BETWEEN 1 AND 100),CHECK(unit_price>=0));
CREATE TABLE diagnostics(order_id INT NOT NULL,test_key VARCHAR(60) NOT NULL,result ENUM('Не проверено','Норма','Проблема','Не применимо') NOT NULL,note VARCHAR(1000) NOT NULL DEFAULT '',staff_id INT NOT NULL,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(order_id,test_key),FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(staff_id) REFERENCES staff(id));
